using Essco.Application.HumanResources;
namespace Essco.Tests.Unit.HumanResources; public sealed class EmployeeBackgroundTests { [Fact] public async Task Rejects_experience_without_company() { var r = new Repo(); var s = new EmployeeBackgroundService(r); var ok = await s.AddExperienceAsync("1", new("", "", "Puesto", new(2020, 1, 1), new(2021, 1, 1), "", "", ""), default); Assert.False(ok); Assert.False(r.Called); } [Fact] public async Task Accepts_valid_education() { var r = new Repo(); var s = new EmployeeBackgroundService(r); var ok = await s.AddEducationAsync("1", new("U", "Título", new(2020, 1, 1), new(2021, 1, 1), false, "Bachiller"), default); Assert.True(ok); Assert.True(r.Called); } private sealed class Repo : IEmployeeBackgroundRepository { public bool Called { get; private set; } public ValueTask<IReadOnlyCollection<EmployeeEducation>> ListEducationAsync(string i, CancellationToken t) => ValueTask.FromResult<IReadOnlyCollection<EmployeeEducation>>([]); public ValueTask<IReadOnlyCollection<EmployeeExperience>> ListExperienceAsync(string i, CancellationToken t) => ValueTask.FromResult<IReadOnlyCollection<EmployeeExperience>>([]); public ValueTask<bool> AddEducationAsync(string i, EmployeeEducation x, CancellationToken t) { Called = true; return ValueTask.FromResult(true); } public ValueTask<bool> AddExperienceAsync(string i, EmployeeExperience x, CancellationToken t) { Called = true; return ValueTask.FromResult(true); } public ValueTask<bool> DeleteEducationAsync(string i, string k, CancellationToken t) => ValueTask.FromResult(true); public ValueTask<bool> DeleteExperienceAsync(string i, string k, CancellationToken t) => ValueTask.FromResult(true); } }
